const GEAR_TIERS=[['iron','玄鐵',40],['silver','月銀',80],['gold','曜金',120],['diamond','星晶',160]];
const CAPES=[{id:'ember',name:'晨曦披風',price:0,color:'#c87550',description:'暖橙色披風，陪你踏上最初的冒險。'},{id:'forest',name:'森林守護披風',price:60,color:'#628462',description:'翠綠披風，將森林的祝福披在肩上。'},{id:'night',name:'星光魔法披風',price:120,color:'#77719d',description:'紫色披風，呼應星光與魔法。'}];
const WEAPONS=[{id:'dawn',name:'晨光長劍',price:0,description:'明亮的鋼刃與金色護手，勇者的初始武器。'},{id:'crystal',name:'星晶光刃',price:150,description:'青紫色水晶劍，揮出閃耀的星光斬擊。'},{id:'wand',name:'星環法杖',price:100,description:'以藍色寶石凝聚魔法，發射星環魔法彈。'}];
function gearCatalog(slot){if(slot==='cape')return CAPES;if(slot==='weapon')return WEAPONS;const name=GEAR_SLOTS.find(x=>x[0]===slot)?.[1]||'';return [{id:'none',name:'原裝'+name,price:0,description:'保留勇者原本的冒險服裝。'},...GEAR_TIERS.map(([id,prefix,price])=>({id,name:prefix+name,price,description:'手繪'+prefix+'裝備，穿戴後會顯示在戰鬥中。'}))]}
function normalizeGear(target,source=target){const raw=source.gear||{},owned=Array.isArray(source.ownedGear)?source.ownedGear:[];target.ownedGear=['weapon:dawn',...owned.filter(k=>typeof k==='string'&&GEAR_SLOTS.some(([slot])=>slot!=='cape'&&gearCatalog(slot).some(i=>slot+':'+i.id===k)))];target.ownedGear=[...new Set(target.ownedGear)];target.gear={};for(const [slot]of GEAR_SLOTS){if(slot==='cape')continue;const fallback=slot==='weapon'?'dawn':'none';target.gear[slot]=gearCatalog(slot).some(i=>i.id===raw[slot])&&(raw[slot]==='none'||target.ownedGear.includes(slot+':'+raw[slot]))?raw[slot]:fallback}}
let equipmentTab='weapon',equipmentPreview=null,heroRenderId=0;
const defaults=()=>({finalSelectionVersion:1,endPuzzleVersion:1,endPuzzles:{},summonSeen:false,storyMistakes:{},finalReviewVersion:2,finalResult:null,legacyReview:false,version:1,coins:0,items:{potion:0,revive:0},retryLimits:{},records:{},progress:[0,0,0,0,0,0],routes:{},puzzles:{},equipped:'ember',owned:['ember'],sound:true,ghost:true,finalDone:false,finalQueue:null,finalIndex:0,combat:null,gear:{weapon:'dawn',helmet:'none',chest:'none',gloves:'none',boots:'none'},ownedGear:['weapon:dawn']});
let state=defaults(),storageOK=true,loadedSnapshot=null;
function loadAdventure(){state=defaults();storageOK=true;loadedSnapshot=null;try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&saved.version===1&&Array.isArray(saved.progress)&&saved.progress.length===6){loadedSnapshot=saved;state={...state,...saved};state.progress=state.progress.map((n,i)=>Math.min(lessonTotal(i),Math.max(0,Math.floor(Number(n)||0))))}}catch(e){storageOK=false}normalizeEndPuzzles(state,loadedSnapshot||state);normalizeGear(state);normalizeItems(state);normalizeReview(state,loadedSnapshot||state)}
loadAdventure();
let screen='map',active=null,board=null,viewLesson=0,reviewKind='s',pending=null,audioCtx=null;let timer=0;
function normalizeReview(target,source=target){
 const schema=source.finalReviewVersion===2,validKeys=new Set(D.lessons.flatMap((l,i)=>Q.required(l).map(c=>i+':'+c.char))),mistakes={};
 if(schema){for(const [key,n]of Object.entries(source.storyMistakes||{}))if(validKeys.has(key)&&Number.isFinite(n)&&n>0)mistakes[key]=Math.floor(n)}
 else{D.lessons.forEach((l,i)=>Q.required(l).slice(0,target.progress[i]||0).forEach(c=>{const key=i+':'+c.char,n=Number(source.records?.[key]?.mistakes)||0;if(n>0)mistakes[key]=n}));}
 let queue=schema&&Array.isArray(source.finalQueue)?source.finalQueue:null;let migratedIndex=source.finalIndex;
 const expected=Q.reviewQueue(D.lessons,mistakes);
 const former=Q.reviewQueue(D.lessons,mistakes,1);
 if(source.finalSelectionVersion!==1&&queue&&Number.isInteger(migratedIndex)&&migratedIndex>=0&&migratedIndex<=queue.length&&queue.length===former.length&&queue.every((key,i)=>key===former[i])){const completed=new Set(queue.slice(0,migratedIndex));queue=expected;migratedIndex=expected.filter(key=>completed.has(key)).length}
 if(queue&&queue.length===expected.length&&queue.every((k,i)=>k===expected[i]))queue=Q.finalReviewQueue(D.lessons,mistakes,queue);
 const validQueue=queue&&queue.length===Math.max(10,expected.length)&&new Set(queue.map(k=>k.split(':')[1])).size===queue.length&&queue.every(k=>validKeys.has(k))&&expected.every(k=>queue.includes(k));
 const unlocked=target.progress.length===6&&target.progress.every((n,i)=>regionCleared(i,target));
 const rawIndex=migratedIndex;
 const rawCombat=source.combat;
 const validIndex=Number.isInteger(rawIndex)&&rawIndex>=0&&rawIndex<=(queue?.length||0);
 target.storyMistakes=mistakes;target.finalQueue=unlocked&&validQueue&&validIndex?[...queue]:null;
 target.finalIndex=target.finalQueue?rawIndex:0;target.finalReviewVersion=2;target.finalSelectionVersion=1;
 target.finalDone=unlocked&&schema&&source.finalDone===true;
 target.finalResult=target.finalDone&&source.finalResult&&Number.isInteger(source.finalResult.count)?{count:Math.max(0,Math.min(totalWords(),source.finalResult.count)),perfect:source.finalResult.perfect===true,reward:0}:null;
 target.legacyReview=source.legacyReview===true||!schema;
 if(rawCombat?.key==='final:review-v2'&&target.finalQueue&&Number.isFinite(rawCombat.hp))target.combat={key:'final:review-v2',hp:Math.max(0,Math.min(100,rawCombat.hp))};
 else if(rawCombat?.key?.startsWith('final:'))target.combat=null;
}
function regionCleared(i,target=state){return target.progress[i]===lessonTotal(i)&&target.endPuzzles?.[i]===true}
function crystalsReady(){return state.progress.length===6&&state.progress.every((n,i)=>regionCleared(i))}
function wrongWords(){return Q.reviewQueue(D.lessons,state.storyMistakes)}
function finalSummary(){const priority=wrongWords().length,n=Math.max(10,priority);return state.finalQueue?'複習 '+state.finalIndex+' / '+state.finalQueue.length+' 字 · 魔龍剩餘 '+((state.finalQueue.length-state.finalIndex)*30)+' HP':priority+' 個重點錯字＋'+(n-priority)+' 個補充生字 · 共 '+n+' 字 · 魔龍 '+(n*30)+' HP'}
const count=()=>state.progress.reduce((a,b)=>a+b,0),cleared=()=>state.progress.filter((n,i)=>regionCleared(i)).length;
function save(){state.campaignId=KEY;try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){storageOK=false}$('#coins').textContent=state.coins;$('#sound').textContent=state.sound?'♫':'♪';$('#sound').setAttribute('aria-pressed',String(state.sound));$('#sound').setAttribute('aria-label',state.sound?'音效已開啟，點選關閉':'音效已關閉，點選開啟');$('#sound').title=state.sound?'關閉音效':'開啟音效';$('#save-status').textContent=storageOK?'✓ 進度已自動保存於這個瀏覽器':'此瀏覽器無法保存，請先匯出進度';document.documentElement.style.setProperty('--cape',capeColor())}
