 $('#summon-skip').onclick=()=>{reveal();$('#summon-enter').focus()};$('#summon-enter').onclick=()=>{if(screen==='summon')startFinal()};$('#summon-home').onclick=()=>{state.summonSeen=true;save();renderMap()};
